insert into tax_templates
  (country, code, name, name_i18n, description, amount_type, amount, applies_to, treatment,
   valid_from, valid_to, legal_reference, vat_category, exemption_code, sequence,
   tax_kind, recoverable, conditions, jurisdiction, price_include, cash_basis,
   cash_basis_transition_account_code, source_key,
   applies_seller_territory, applies_buyer_territory, applies_supply_territory,
   applies_supply_vs_seller)
values
  ('RS', 'RS-P-10', 'PDV 10% — posebna stopa (nabavka), odbitni', '{"en":"VAT 10% — reduced rate (purchase), deductible"}'::jsonb, null, 'percent', 10, 'purchase', 'domestic', date '2012-10-01', null, 'Zakon o porezu na dodatu vrednost, član 23. stav 2. i član 28 — pravo na odbitak prethodnog poreza po istim pravilima, za nabavke oporezovane posebnom stopom.', 'S', null, 70, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'zakon-pdv', null, null, null, null),
  ('RS', 'RS-P-20', 'PDV 20% — opšta stopa (nabavka), odbitni', '{"en":"VAT 20% — standard rate (purchase), deductible"}'::jsonb, null, 'percent', 20, 'purchase', 'domestic', date '2012-10-01', null, 'Zakon o porezu na dodatu vrednost, član 23. stav 1. i član 28 — obveznik ima pravo da od PDV koji duguje odbije prethodni porez koji mu je iskazan u računu za nabavku dobara i usluga korišćenih za promet dobara i usluga sa pravom na odbitak.', 'S', null, 60, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'zakon-pdv', null, null, null, null),
  ('RS', 'RS-P-EXEMPT', 'Nabavka bez PDV — oslobođena delatnost dobavljača (npr. osiguranje, finansijske usluge)', '{"en":"Purchase with no VAT — supplier''s exempt activity"}'::jsonb, null, 'percent', 0, 'purchase', 'exempt', date '2004-07-24', null, 'Zakon o porezu na dodatu vrednost, član 25 — dobavljač ne obračunava PDV na promet oslobođen bez prava na odbitak (npr. usluge osiguranja i reosiguranja iz stava 2. tačka 1)), pa račun ne sadrži iznos PDV koji bi kupac mogao da odbije.', 'E', null, 80, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'zakon-pdv', null, null, null, null),
  ('RS', 'RS-P-IMPORT', 'Uvoz dobara — PDV plaćen na carini, opšta stopa, odbitni', '{"en":"Import of goods — VAT paid at customs, standard rate, deductible"}'::jsonb, null, 'percent', 20, 'purchase', 'import', date '2012-10-01', null, 'Zakon o porezu na dodatu vrednost, član 10. stav 1. tačka 5) — poreski dužnik je lice koje uvozi dobro; član 26 i 46 — osnovica kod uvoza je vrednost dobra utvrđena po carinskim propisima, uvećana za carinu i druge dažbine, a PDV se plaća istovremeno sa carinskim dugom. Član 28 — PDV plaćen pri uvozu odbija se u poreskom periodu u kojem je plaćen (član 49. stav 5).', null, null, 90, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'zakon-pdv', null, null, null, null),
  ('RS', 'RS-P-RC-CONSTR', 'Građevinski radovi preko 500.000 dinara — samoobračunati PDV', '{"en":"Construction works over RSD 500,000 — self-assessed VAT"}'::jsonb, null, 'percent', 20, 'purchase', 'domestic_reverse_charge', date '2015-10-15', null, 'Zakon o porezu na dodatu vrednost, član 10. stav 2. tačka 3) — primalac dobara i usluga iz oblasti građevinarstva je poreski dužnik za promet veći od 500.000 dinara bez PDV izvršen od strane obveznika PDV; sačinjava interni račun (član 42. stav 10) na kojem sam obračunava PDV po stopi koju bi primenio izvođač, i istovremeno ostvaruje pravo na odbitak prethodnog poreza (član 28) ako dobra/usluge koristi za sopstveni oporezovani promet.', 'AE', null, 100, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'zakon-pdv', null, null, null, null),
  ('RS', 'RS-P-RC-FOREIGN', 'Usluga stranog lica koje nije obveznik PDV u Republici — samoobračunati PDV', '{"en":"Service from a foreign person not registered for VAT — self-assessed VAT"}'::jsonb, null, 'percent', 20, 'purchase', 'foreign_services_received', date '2004-07-24', null, 'Zakon o porezu na dodatu vrednost, član 10. stav 1. tačka 3) — poreski dužnik je primalac dobara i usluga ako strano lice nije obveznik PDV u Republici, nezavisno od toga da li u Republici ima stalnu poslovnu jedinicu. Primalac sačinjava interni račun (član 42. stav 10) i sam obračunava i deklariše PDV po stopi koja bi se primenila da je uslugu pružio domaći obveznik; pravo na odbitak prethodnog poreza po članu 28 postoji ako se usluga koristi za sopstveni oporezovani promet.', null, null, 110, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'zakon-pdv', null, null, null, null),
  ('RS', 'RS-S-10', 'PDV 10% — posebna stopa (promet)', '{"en":"VAT 10% — reduced rate (sale)"}'::jsonb, null, 'percent', 10, 'sale', 'domestic', date '2012-10-01', null, 'Zakon o porezu na dodatu vrednost, član 23. stav 2 — po posebnoj stopi PDV od 10% oporezuje se promet dobara i usluga taksativno nabrojanih u tač. 1)–21) ovog stava (hleb i pekarski proizvodi, mleko, brašno, šećer, jestivo ulje; sveže, rashlađeno i smrznuto voće, povrće, meso, riba i jaja; lekovi; ortotička i protetička sredstva; đubriva i seme; udžbenici; dnevne novine; ogrevno drvo; usluge smeštaja u ugostiteljskim objektima; ulaznice za bioskop, pozorište, koncerte, muzeje i sl.; prirodni gas; toplotna energija za grejanje; prenos prava raspolaganja na stambenim objektima; voda za piće i usluge vodovodne mreže; prečišćavanje otpadnih voda; upravljanje komunalnim otpadom; prevoz putnika i dr.).', 'S', null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'zakon-pdv', null, null, null, null),
  ('RS', 'RS-S-20', 'PDV 20% — opšta stopa (promet)', '{"en":"VAT 20% — standard rate (sale)"}'::jsonb, null, 'percent', 20, 'sale', 'domestic', date '2012-10-01', null, 'Zakon o porezu na dodatu vrednost, član 23. stav 1 — opšta stopa PDV za oporezivi promet dobara i usluga ili uvoz dobara iznosi 20%.', 'S', null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'zakon-pdv', null, null, null, null),
  ('RS', 'RS-S-EXEMPT-EDU', 'Usluge obrazovanja — oslobođeno bez prava na odbitak', '{"en":"Educational services — exempt without credit"}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2004-07-24', null, 'Zakon o porezu na dodatu vrednost, član 25. stav 2. tačka 13) — PDV se ne plaća na promet usluga obrazovanja (predškolsko, osnovno, srednje, više i visoko) i stručne prekvalifikacije, kao i sa njima neposredno povezanog prometa dobara i usluga od strane lica registrovanih za obavljanje tih delatnosti, ako se te delatnosti obavljaju u skladu sa propisima koji uređuju tu oblast. Nema prava na odbitak prethodnog poreza po ovom prometu (član 30).', 'E', null, 40, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'zakon-pdv', null, null, null, null),
  ('RS', 'RS-S-EXPORT', 'Izvoz dobara — oslobođeno sa pravom na odbitak', '{"en":"Export of goods — exempt with credit"}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2004-07-24', null, 'Zakon o porezu na dodatu vrednost, član 24. stav 1. tač. 2) i 3) — PDV se ne plaća na promet dobara koja obveznik, ili treće lice po njegovom nalogu, odnosno inostrani primalac, šalje ili otprema u inostranstvo; obveznik zadržava pravo na odbitak prethodnog poreza po ovom prometu.', 'G', null, 30, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'zakon-pdv', null, null, null, null),
  ('RS', 'RS-S-RC-CONSTR', 'Građevinski radovi preko 500.000 dinara — PDV plaća primalac', '{"en":"Construction works over RSD 500,000 — recipient accounts for VAT"}'::jsonb, null, 'percent', 0, 'sale', 'domestic_reverse_charge', date '2015-10-15', null, 'Zakon o porezu na dodatu vrednost, član 10. stav 2. tačka 3) — poreski dužnik je primalac dobara i usluga iz oblasti građevinarstva, obveznik PDV, za promet izvršen od strane drugog obveznika PDV, ako je vrednost tog prometa veća od 500.000 dinara bez PDV; izvršilac ne obračunava PDV na računu i navodi napomenu o odredbi zakona na osnovu koje PDV nije obračunat (član 42. stav 5. tačka 9)). Osnovica ovog prometa se, prema opisu polja 003 Obrasca PPPDV (član 13. Pravilnika o obliku i sadržini poreske prijave PDV), iskazuje u istoj rubrici prometa po opštoj stopi kao i redovna prodaja po toj stopi — ovaj paket prati to tumačenje jer PPPDV/POPDV ne razlikuje posebnu rubriku za samo ovu vrstu prometa; potvrditi sa knjigovođom pre primene na stvarnu transakciju (vidi README.md).', 'AE', null, 50, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'zakon-pdv', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
  amount_type     = excluded.amount_type,
