values
  ('RS', 'RS-PPPDV', 'Poreska prijava poreza na dodatu vrednost (Obrazac PPPDV)', array['month', 'quarter']::declaration_period[], null, date '2018-01-01', null, 'Pravilnik o obliku i sadržini prijave za evidentiranje obveznika PDV, postupku evidentiranja i brisanja iz evidencije i o obliku i sadržini poreske prijave PDV, čl. 11–13 — obveznik podnosi poresku prijavu na Obrascu PPPDV; ovaj paket transkribuje deo III (promet dobara i usluga), deo IV (prethodni porez) i deo V (poreska obaveza) tog obrasca, čija se polja pune na osnovu odgovarajućih polja Obrasca POPDV. Redni brojevi 1 (polje 001, promet oslobođen sa pravom na odbitak), 2 (polje 002, promet oslobođen bez prava na odbitak), 7 (polja 007/107, PDV nadoknada isplaćena poljoprivrednicima po posebnom paušalnom režimu iz čl. 34 Zakona) i indikator povraćaja (polje 011) nisu dostignuti nijednom porezom ovog paketa i ostaju deklarisani, ali prazni u zlatnom scenariju — vidi README.md.', true,'day_of_month_after_period'::filing_deadline_rule, 15, null, 'Zakon o porezu na dodatu vrednost, član 50. stav 1 — obveznik podnosi poresku prijavu poreskom organu na propisanom obrascu, u roku od 15 dana po isteku poreskog perioda; isti rok važi za plaćanje PDV.', 'zakon-pdv', null, 1, 'Pravilnik o obliku i sadržini prijave za evidentiranje obveznika PDV..., član 26 — u obrasce EPPDV i PPPDV iznosi se upisuju, odnosno iskazuju u dinarima, bez decimala.', 'pravilnik-pppdv')
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  rounding_unit       = excluded.rounding_unit,
  rounding_reference  = excluded.rounding_reference,
  rounding_source_key = excluded.rounding_source_key,
  file_format         = excluded.file_format;

