insert into statement_templates
  (code, country, chart_code, name, kind, framework, valid_from, valid_to, legal_reference,
   source_key)
values
  ('RS-BS', 'RS', 'default', 'Bilans stanja', 'balance_sheet', 'Pravilnik 89/2020 — Prilog 1', date '2021-01-01', null, 'Pravilnik o sadržini i formi obrazaca finansijskih izveštaja..., Prilog 1 (Bilans stanja). Mikro pravna lica iskazuju u ovom obrascu skraćeni obim podataka, samo na pozicijama označenim slovnim oznakama i rimskim brojevima (član 6. stav 2. Pravilnika); ovaj paket transkribuje tačno taj skraćeni (abridged) nivo, potvrđen sadržinom obrasca BON-JN Agencije za privredne registre. Redovi za koje Kontni okvir ne propisuje poseban trocifreni račun po ročnosti (dugoročna aktivna/pasivna vremenska razgraničenja, kratkoročna rezervisanja, sredstva/obaveze poslovanja koje se obustavlja, gubitak iznad visine kapitala, obračun za razdvajanje nerealizovanih dobitaka od gubitaka po instrumentima iz grupe 33) nisu transkribovani jer bi zahtevali analitiku koju ovaj paket ne uvodi — videti README.md.', 'pravilnik-fin-izvestaji'),
  ('RS-IS', 'RS', 'default', 'Bilans uspeha', 'income_statement', 'Pravilnik 89/2020 — Prilog 2', date '2021-01-01', null, 'Pravilnik o sadržini i formi obrazaca finansijskih izveštaja..., Prilog 2 (Bilans uspeh). Kao i kod Bilansa stanja, mikro pravna lica iskazuju skraćeni obim podataka samo na pozicijama označenim slovnim oznakama i rimskim brojevima (član 8. stav 2. Pravilnika). Forma razlikuje za svaki međuzbir poseban red „dobitak” i poseban red „gubitak” (npr. V/G Poslovni dobitak/gubitak, E/Ž Dobitak/gubitak iz finansiranja, M/N, P/R, Ć/U), od kojih se u svakom periodu popunjava samo jedan; ovaj paket, kao i paket za Ukrajinu, pojednostavljuje svaki takav par u jedan red sa znakom (pozitivna vrednost — dobitak, negativna — gubitak). Redovi za prihode/rashode od diskontinuiranog poslovanja, promene računovodstvenih politika i lična primanja preduzetnika nisu transkribovani jer Kontni okvir ovog paketa ne uvodi zasebne račune za njih — videti README.md.', 'pravilnik-fin-izvestaji')
on conflict (code) do update set
  country         = excluded.country,
  chart_code      = excluded.chart_code,
  name            = excluded.name,
  kind            = excluded.kind,
  framework       = excluded.framework,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  source_key      = excluded.source_key;

