update country_defaults set
  numbering_gapless             = false,
  number_format                 = '{CODE}-{YYYY}-{NNNN}',
  legal_payment_days            = 60,
  late_payment_reference        = 'Zakon o rokovima izmirenja novčanih obaveza u komercijalnim transakcijama, član 5 — poverilac ima pravo na naknadu za kašnjenje u iznosu od 20.000 dinara po neizmirenoj obavezi, pored zatezne kamate koju uređuje poseban zakon.',
  numbering_legal_reference     = 'Zakon o porezu na dodatu vrednost, član 42. stav 5. tačka 2) — račun sadrži mesto i datum izdavanja i redni broj računa. Zakon ne propisuje da niz mora biti bez prekida; format ovde je primer redosleda po seriji i godini, a ne jedini nametnuti oblik.',
  numbering_source_key          = 'zakon-pdv',
  payment_terms_legal_reference = 'Zakon o rokovima izmirenja novčanih obaveza u komercijalnim transakcijama, član 3. st. 1. i 2. — ugovorom između privrednih subjekata ne može se predvideti rok duži od 60 dana; ako rok nije ugovoren, ili ne postoji pisani ugovor, ili je ugovoren duži rok, dužnik je dužan da bez prethodne opomene izmiri obavezu najkasnije u roku od 60 dana.',
  payment_terms_source_key      = 'zakon-rokovi-placanja',
  tax_point_rule                = 'earliest_of_delivery_or_payment',
  tax_point_legal_reference     = 'Zakon o porezu na dodatu vrednost, član 16. stav 1. — poreska obaveza nastaje danom kada se najranije izvrši promet dobara i usluga, ili naplata odnosno plaćanje ako je naknada naplaćena pre prometa, ili nastanak obaveze plaćanja carinskog duga kod uvoza. Nijedna od dve prve radnje ne pretpostavlja drugu, pa je ovo pravilo najbliže vokabularu `earliest_of_delivery_or_payment`, a ne izuzetku od pravila računa kao u Belgiji ili Luksemburgu.',
  tax_point_source_key          = 'zakon-pdv',
  posted_edit_policy            = 'reversal_only',
  posted_edit_policy_legal_reference = 'Zakon o računovodstvu, član 9 — ispravka greške u poslovnim knjigama vrši se na način koji ne dozvoljava brisanje ili izmenu bez traga; Zakon o porezu na dodatu vrednost, član 42. stav 10. i član 21 — ispravka osnovice i obračunatog PDV vrši se sastavljanjem računa o smanjenju/povećanju osnovice (knjižnog odobrenja/zaduženja), nikada brisanjem izdatog računa.',
  posted_edit_policy_source_key = 'zakon-racunovodstvo',
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_legal_reference      = 'Zakon o elektronskom fakturisanju, član 24 — obaveza izdavanja i čuvanja elektronske fakture u transakcijama između subjekata privatnog sektora primenjuje se od 1. januara 2023. godine; obaveza subjekta privatnog sektora da izda elektronsku fakturu subjektu javnog sektora primenjuje se od 1. maja 2022, a obaveza prijema i čuvanja faktura izdatih od javnog sektora od 1. jula 2022. Sistem elektronskih faktura (SEF, efaktura.gov.rs) je državna platforma preko koje se fakture obavezno izdaju, šalju i primaju (član 5); nije reč o razmeni preko mreže vršnjaka kao kod Peppol-a, i faktura se ne sastavlja prema jednom od profila izgrađenih na semantičkom modelu EN 16931 (Peppol BIS, Factur-X, XRechnung, PINT), nego u XML formatu koji propisuje Ministarstvo finansija (Pravilnik o elektronskom fakturisanju). `profile` je zato ostavljen prazan, a ne popunjen uslovnim nacionalnim nazivom. `party_scheme` i `vat_scheme` su takođe prazni: Srbija nema ISO 6523 identifikacionu šemu registrovanu u mreži Peppol — poreski identifikacioni broj (PIB) i matični broj se razmenjuju u samom XML zapisu SEF-a, van ove šeme. Zakon takođe uvodi posebnu obavezu elektronskog evidentiranja obračuna PDV u sistemu elektronskih faktura (član 4), sa rokom jednakim roku za podnošenje poreske prijave (član 4. stav pretposlednji) — ovaj vid evidentiranja je odvojen od same deklaracije PPPDV koju ovaj paket modeluje kao tax_report.json i nije nešto što socle danas ume da predstavi; vidi README.md i docs/international.md, odeljak „From Serbia”.',
  einvoice_source_key           = 'zakon-efakturisanje',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'RS';

insert into legal_mention_templates
  (country, code, applies_when, text, text_i18n, sequence, valid_from, valid_to, legal_reference)
values
  ('RS', 'reverse_charge', 'reverse_charge', 'PDV obračunava i plaća primalac dobara/usluga, u skladu sa članom 10. Zakona o porezu na dodatu vrednost.', '{"en":"VAT is accounted for and paid by the recipient, in accordance with article 10 of the Law on Value Added Tax."}'::jsonb, 10, date '1970-01-01', null, 'Zakon o porezu na dodatu vrednost, član 10. stav 2. tačka 3) i stav 1. tačka 3) — poreski dužnik je primalac dobara i usluga iz oblasti građevinarstva čija je vrednost prometa veća od 500.000 dinara bez PDV, odnosno primalac usluge od stranog lica koje nije evidentirani obveznik PDV u Republici.')
on conflict (country, code) do update set
  applies_when    = excluded.applies_when,
  text            = excluded.text,
  text_i18n       = excluded.text_i18n,
  sequence        = excluded.sequence,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference;
